     credential: cert(serviceAccount),
     databaseURL: 'https://<DATABASE_NAME>.firebaseio.com',
   });

   const functions = getFunctions();
   const db = getFirestore(app);

   const languageClient = new LanguageServiceClient();

   export const analyzeSentiment = httpsCallable(functions, 'analyzeSentiment');
   ```

   Remplacez `path/to/credentials.json` par le chemin absolu vers votre fichier de compte Google Cloud.

4. Créez un nouveau fichier `pages/api/analyzeSentiment.js` et ajoutez le code suivant pour appeler l'API de Google Cloud Natural Language et analyser le sentiment d'un tweet:

   ```javascript
   import { httpsCallable } from 'firebase-admin/functions';
   import { Sentiment, SentimentDocument } from '@google-cloud/language';

   export const analyzeSentiment = httpsCallable((req, context) => {
     const { text } = req.data;

     return new Promise((resolve, reject) => {
       const sentiment = new Sentiment({ language: 'en' });

       sentiment.analyzeSentiment({ document: { type: SentimentDocument.PLAIN_TEXT, content: text } })
         .then(results => {
           const sentimentScore = results[0].documentSentiment.score;
           const sentimentMagnitude = results[0].documentSentiment.magnitude;

           resolve({ score: sentimentScore, magnitude: sentimentMagnitude });
         })
         .catch(error => {
           reject(error);
         });
     });
   });
   ```

5. Enfin, créez un nouveau fichier `pages/api/[id].js` et ajoutez le code suivant pour collecter le tweet à analyser et appeler l'API `analyzeSentiment`:

   ```javascript
   import { getFirestore, collection, getDocs } from 'firebase-admin/firestore';
   import { analyzeSentiment } from './analyzeSentiment';

   export default async (req, res) => {
     const { id } = req.query;

     const db = getFirestore();

     const tweetRef = collection(db, 'tweets');
     const tweetDoc = await getDocs(tweetRef).where('id', '==', id).limit(1).get();

     if (tweetDoc.empty) {
       return res.status(404).send('Tweet not found');
     }

     const { text } = tweetDoc.docs[0].data();

     const { data: sentiment } = await analyzeSentiment({ text });

     res.json(sentiment);
   };
   ```

   Remplacez `tweets` par le nom de votre collection de tweets dans votre base de données Firebase.

